63 namespace DirectX
64 {
65     class GamePad
66     {
67     public:
68         GamePad() noexcept(false);
69 
70         GamePad(GamePad&&) noexcept;
71         GamePad& operator= (GamePad&&) noexcept;
72 
73         GamePad(GamePad const&) = delete;
74         GamePad& operator=(GamePad const&) = delete;
75 
76         virtual ~GamePad();
77 
78     #if defined(USING_GAMEINPUT) || defined(USING_WINDOWS_GAMING_INPUT) || defined(_XBOX_ONE)
79         static constexpr int MAX_PLAYER_COUNT = 8;
80     #else
81         static constexpr int MAX_PLAYER_COUNT = 4;
82     #endif
83 
84         static constexpr int c_MostRecent = -1;
85 
86     #ifdef USING_GAMEINPUT
87         static constexpr int c_MergedInput = -2;
88     #endif
89 
90         enum DeadZone
91         {
92             DEAD_ZONE_INDEPENDENT_AXES = 0,
93             DEAD_ZONE_CIRCULAR,
94             DEAD_ZONE_NONE,
95         };
96 
97         struct Buttons
98         {
99             bool a;
100             bool b;
101             bool x;
102             bool y;
103             bool leftStick;
104             bool rightStick;
105             bool leftShoulder;
106             bool rightShoulder;
107             union
108             {
109                 bool back;
110                 bool view;
111             };
112             union
113             {
114                 bool start;
115                 bool menu;
116             };
117         };
118 
119         struct DPad
120         {
121             bool up;
122             bool down;
123             bool right;
124             bool left;
125         };
126 
127         struct ThumbSticks
128         {
129             float leftX;
130             float leftY;
131             float rightX;
132             float rightY;
133         };
134 
135         struct Triggers
136         {
137             float left;
138             float right;
139         };
140 
141         struct State
142         {
143             bool        connected;
144             uint64_t    packet;
145             Buttons     buttons;
146             DPad        dpad;
147             ThumbSticks thumbSticks;
148             Triggers    triggers;
149 
150             bool __cdecl IsConnected() const noexcept { return connected; }
151 
152             // Is the button pressed currently?
153             bool __cdecl IsAPressed() const noexcept { return buttons.a; }
154             bool __cdecl IsBPressed() const noexcept { return buttons.b; }
155             bool __cdecl IsXPressed() const noexcept { return buttons.x; }
156             bool __cdecl IsYPressed() const noexcept { return buttons.y; }
157 
158             bool __cdecl IsLeftStickPressed() const noexcept { return buttons.leftStick; }
159             bool __cdecl IsRightStickPressed() const noexcept { return buttons.rightStick; }
160 
161             bool __cdecl IsLeftShoulderPressed() const noexcept { return buttons.leftShoulder; }
162             bool __cdecl IsRightShoulderPressed() const noexcept { return buttons.rightShoulder; }
163 
164             bool __cdecl IsBackPressed() const noexcept { return buttons.back; }
165             bool __cdecl IsViewPressed() const noexcept { return buttons.view; }
166             bool __cdecl IsStartPressed() const noexcept { return buttons.start; }
167             bool __cdecl IsMenuPressed() const noexcept { return buttons.menu; }
168 
169             bool __cdecl IsDPadDownPressed() const noexcept { return dpad.down; }
170             bool __cdecl IsDPadUpPressed() const noexcept { return dpad.up; }
171             bool __cdecl IsDPadLeftPressed() const noexcept { return dpad.left; }
172             bool __cdecl IsDPadRightPressed() const noexcept { return dpad.right; }
173 
174             bool __cdecl IsLeftThumbStickUp() const noexcept { return (thumbSticks.leftY > 0.5f) != 0; }
175             bool __cdecl IsLeftThumbStickDown() const noexcept { return (thumbSticks.leftY < -0.5f) != 0; }
176             bool __cdecl IsLeftThumbStickLeft() const noexcept { return (thumbSticks.leftX < -0.5f) != 0; }
177             bool __cdecl IsLeftThumbStickRight() const noexcept { return (thumbSticks.leftX > 0.5f) != 0; }
178 
179             bool __cdecl IsRightThumbStickUp() const noexcept { return (thumbSticks.rightY > 0.5f) != 0; }
180             bool __cdecl IsRightThumbStickDown() const noexcept { return (thumbSticks.rightY < -0.5f) != 0; }
181             bool __cdecl IsRightThumbStickLeft() const noexcept { return (thumbSticks.rightX < -0.5f) != 0; }
182             bool __cdecl IsRightThumbStickRight() const noexcept { return (thumbSticks.rightX > 0.5f) != 0; }
183 
184             bool __cdecl IsLeftTriggerPressed() const noexcept { return (triggers.left > 0.5f) != 0; }
185             bool __cdecl IsRightTriggerPressed() const noexcept { return (triggers.right > 0.5f) != 0; }
186         };
187 
188         struct Capabilities
189         {
190             enum Type
191             {
192                 UNKNOWN = 0,
193                 GAMEPAD,
194                 WHEEL,
195                 ARCADE_STICK,
196                 FLIGHT_STICK,
197                 DANCE_PAD,
198                 GUITAR,
199                 GUITAR_ALTERNATE,
200                 DRUM_KIT,
201                 GUITAR_BASS = 11,
202                 ARCADE_PAD = 19,
203             };
204 
205             bool                connected;
206             Type                gamepadType;
207         #ifdef USING_GAMEINPUT
208             APP_LOCAL_DEVICE_ID id;
209         #elif defined(USING_WINDOWS_GAMING_INPUT)
210             std::wstring        id;
211         #else
212             uint64_t            id;
213         #endif
214             uint16_t            vid;
215             uint16_t            pid;
216 
217             Capabilities() noexcept : connected(false), gamepadType(UNKNOWN), id{}, vid(0), pid(0) {}
218 
219             bool __cdecl IsConnected() const noexcept { return connected; }
220         };
221 
222         class ButtonStateTracker
223         {
224         public:
225             enum ButtonState
226             {
227                 UP = 0,         // Button is up
228                 HELD = 1,       // Button is held down
229                 RELEASED = 2,   // Button was just released
230                 PRESSED = 3,    // Buton was just pressed
231             };
232 
233             ButtonState a;
234             ButtonState b;
235             ButtonState x;
236             ButtonState y;
237 
238             ButtonState leftStick;
239             ButtonState rightStick;
240 
241             ButtonState leftShoulder;
242             ButtonState rightShoulder;
243 
244             union
245             {
246                 ButtonState back;
247                 ButtonState view;
248             };
249 
250             union
251             {
252                 ButtonState start;
253                 ButtonState menu;
254             };
255 
256             ButtonState dpadUp;
257             ButtonState dpadDown;
258             ButtonState dpadLeft;
259             ButtonState dpadRight;
260 
261             ButtonState leftStickUp;
262             ButtonState leftStickDown;
263             ButtonState leftStickLeft;
264             ButtonState leftStickRight;
265 
266             ButtonState rightStickUp;
267             ButtonState rightStickDown;
268             ButtonState rightStickLeft;
269             ButtonState rightStickRight;
270 
271             ButtonState leftTrigger;
272             ButtonState rightTrigger;
273 
274         #ifdef _PREFAST_
275         #pragma prefast(push)
276         #pragma prefast(disable : 26495, "Reset() performs the initialization")
277         #endif
278             ButtonStateTracker() noexcept { Reset(); }
279         #ifdef _PREFAST_
280         #pragma prefast(pop)
281         #endif
282 
283             void __cdecl Update(const State& state) noexcept;
284 
285             void __cdecl Reset() noexcept;
286 
287             State __cdecl GetLastState() const noexcept { return lastState; }
288 
289         private:
290             State lastState;
291         };
292 
293         // Retrieve the current state of the gamepad of the associated player index
294         State __cdecl GetState(int player, DeadZone deadZoneMode = DEAD_ZONE_INDEPENDENT_AXES);
295 
296         // Retrieve the current capabilities of the gamepad of the associated player index
297         Capabilities __cdecl GetCapabilities(int player);
298 
299         // Set the vibration motor speeds of the gamepad
300         bool __cdecl SetVibration(int player, float leftMotor, float rightMotor, float leftTrigger = 0.f, float rightTrigger = 0.f) noexcept;
301 
302         // Handle suspending/resuming
303         void __cdecl Suspend() noexcept;
304         void __cdecl Resume() noexcept;
305 
306     #ifdef USING_GAMEINPUT
307         void __cdecl RegisterEvents(void* ctrlChanged) noexcept;
308 
309         // Underlying device access
310         _Success_(return)
311             bool __cdecl GetDevice(int player, _Outptr_ IGameInputDevice * *device) noexcept;
312     #elif defined(USING_WINDOWS_GAMING_INPUT) || defined(_XBOX_ONE)
313         void __cdecl RegisterEvents(void* ctrlChanged, void* userChanged) noexcept;
314     #endif
315 
316         // Singleton
317         static GamePad& __cdecl Get();
318 
319     private:
320         // Private implementation.
321         class Impl;
322 
323         std::unique_ptr<Impl> pImpl;
324     };
325 }
326 
327 #ifdef __clang__
328 #pragma clang diagnostic pop
329 #endif
